var campaigns=[],statuses={"Email Sent":{color:"#1abc9c",label:"text-bg-success",icon:"fa-envelope"},"Emails Sent":{color:"#1abc9c",label:"text-bg-success",icon:"fa-envelope"},"In progress":{label:"text-bg-primary"},Queued:{label:"text-bg-info"},Completed:{label:"text-bg-success"},"Email Opened":{color:"#f9bf3b",label:"text-bg-warning",icon:"fa-envelope"},"Email Reported":{color:"#45d6ef",label:"text-bg-info",icon:"fa-bullhorn"},"Clicked Link":{color:"#F39C12",label:"text-bg-clicked",icon:"fa-mouse-pointer"},Success:{color:"#f05b4f",label:"text-bg-danger",icon:"fa-exclamation"},Error:{color:"#6c7a89",label:"text-bg-secondary",icon:"fa-times"},"Error Sending Email":{color:"#6c7a89",label:"text-bg-secondary",icon:"fa-times"},"Submitted Data":{color:"#f05b4f",label:"text-bg-danger",icon:"fa-exclamation"},Unknown:{color:"#6c7a89",label:"text-bg-secondary",icon:"fa-question"},Sending:{color:"#428bca",label:"text-bg-primary",icon:"fa-spinner"},"Campaign Created":{label:"text-bg-success",icon:"fa-rocket"}},statsMapping={sent:"Email Sent",opened:"Email Opened",email_reported:"Email Reported",clicked:"Clicked Link",submitted_data:"Submitted Data"};function deleteCampaign(e){confirm("Delete "+campaigns[e].name+"?")&&api.campaignId.delete(campaigns[e].id).done(function(e){successFlash(e.message),location.reload()})}function renderPieChart(e){return GophishCharts.renderDoughnut({elemId:e.elemId,title:e.title,data:e.data,colors:e.colors,centerFontSize:16})}function generateStatsPieCharts(e){var a=[],t={},s=0;$.each(e,function(e,a){$.each(a.stats,function(e,a){if("total"==e)return s+=a,!0;t[e]?t[e]+=a:t[e]=a})}),$.each(t,function(e,t){if(!(e in statsMapping))return!0;status_label=statsMapping[e],a.push({name:status_label,y:Math.floor(t/s*100),count:t}),a.push({name:"",y:100-Math.floor(t/s*100)});renderPieChart({elemId:e+"_chart",title:status_label,name:e,data:a,colors:[statuses[status_label].color,"#dddddd"]});a=[]})}function generateTimelineChart(e){var a=[];$.each(e,function(e,t){var s=moment.utc(t.created_date).local();t.y=0,t.y+=t.stats.clicked,t.y=Math.floor(t.y/t.stats.total*100),a.push({campaign_id:t.id,name:t.name,x:s.valueOf(),y:t.y})}),GophishCharts.renderOverview({elemId:"overview_chart",title:"Phishing Success Overview",data:a})}$(document).ready(function(){api.campaigns.summary().done(function(e){$("#loading").hide(),(campaigns=e.campaigns).length>0?($("#dashboard").show(),campaignTable=new DataTable("#campaignTable",{columnDefs:[{orderable:!1,targets:"no-sort"},{className:"color-sent",targets:[2]},{className:"color-opened",targets:[3]},{className:"color-clicked",targets:[4]},{className:"color-success",targets:[5]},{className:"color-reported",targets:[6]}],order:[[1,"desc"]]}),campaignRows=[],$.each(campaigns,function(e,a){var t=moment(a.created_date).format("MMMM Do YYYY, h:mm:ss a"),s=statuses[a.status].label||"text-bg-secondary";if(moment(a.launch_date).isAfter(moment()))var n="Scheduled to start: "+moment(a.launch_date).format("MMMM Do YYYY, h:mm:ss a")+"<br><br>Number of recipients: "+a.stats.total;else n="Launch Date: "+moment(a.launch_date).format("MMMM Do YYYY, h:mm:ss a")+"<br><br>Number of recipients: "+a.stats.total+"<br><br>Emails opened: "+a.stats.opened+"<br><br>Emails clicked: "+a.stats.clicked+"<br><br>Submitted Credentials: "+a.stats.submitted_data+"<br><br>Errors : "+a.stats.error+"<br><br>Reported : "+a.stats.email_reported;campaignRows.push([escapeHtml(a.name),t,a.stats.sent,a.stats.opened,a.stats.clicked,a.stats.submitted_data,a.stats.email_reported,'<span class="badge '+s+'" data-bs-toggle="tooltip" data-bs-placement="right" data-bs-html="true" title="'+n+'">'+a.status+"</span>","<div class='float-end'><a class='btn btn-primary' href='/campaigns/"+a.id+"' data-bs-toggle='tooltip' data-bs-placement='left' title='View Results'>                    <i class='fa fa-bar-chart'></i>                    </a>                    <button class='btn btn-danger' onclick='deleteCampaign("+e+")' data-bs-toggle='tooltip' data-bs-placement='left' title='Delete Campaign'>                    <i class='fa fa-trash-o'></i>                    </button></div>"]),bsInitTooltips()}),campaignTable.rows.add(campaignRows).draw(),generateStatsPieCharts(campaigns),generateTimelineChart(campaigns)):$("#emptyMessage").show()}).fail(function(){errorFlash("Error fetching campaigns")})});